<?php
declare(strict_types=1);
function frontend_head(string $title,string $page):void{
 $s=site();$asset=base_url('assets/');
 echo '<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="theme-color" content="#01216c"><meta name="robots" content="noindex,nofollow"><title>'.e($title).' · '.e($s['name']).'</title><link rel="icon" href="'.e($asset).'brand/kitchen-safety.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="'.e($asset).'icons/apple-180.png"><link rel="manifest" href="'.e(base_url('manifest.php')).'"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Kitchen Safety"><meta name="apple-mobile-web-app-status-bar-style" content="default"><link rel="stylesheet" href="'.e($asset).'app.css?v='.APP_VERSION.'"><link rel="stylesheet" href="'.e($asset).'frontend.css?v='.APP_VERSION.'"><script src="'.e($asset).'app.js?v='.APP_VERSION.'" defer></script><script src="'.e($asset).'pwa.js?v='.APP_VERSION.'" defer></script></head><body class="kitchen-page" data-base="'.e(base_url()).'"><a class="skip" href="#main">Skip to content</a>';
 echo '<header class="k-top"><a class="k-brand" href="'.e(url()).'"><img src="'.e($asset).'brand/kitchen-safety.svg" width="44" height="44" alt=""><span>'.e($s['name']).'<small>Kitchen Safety <b>by MustrHQ</b></small></span></a><nav class="k-tabs" aria-label="Kitchen screens">';foreach([''=>'Start','new'=>'Temperatures','history'=>'Date records'] as $p=>$name)echo '<a href="'.e(url($p?'p='.$p:'')).'" '.($p===$page?'aria-current="page"':'').'>'.e($name).'</a>';echo '</nav><a class="btn small k-admin" href="'.e(base_url('admin/')).'">'.icon('settings').' Admin</a></header><main class="k-wrap" id="main">';
 if(isset($_SESSION['flash'])){echo '<div role="status" class="notice success" data-saved-check>'.e($_SESSION['flash']).'</div>';unset($_SESSION['flash']);}
 echo '<div class="k-status"><span class="k-online" data-connection>Online · ready to save</span><span>Kitchen-local time · '.e($s['timezone']).'</span></div>';
}
function frontend_foot():void{
 echo '</main><footer class="k-footer"><span>MustrHQ Kitchen Safety · '.APP_VERSION.'</span><a href="'.e(url('p=help')).'">Kitchen guide</a><button type="button" class="text-button" data-install>Install on tablet</button><span>Names entered here are self-reported.</span></footer><dialog class="install-dialog" data-install-dialog><button type="button" class="btn small" data-close-install>Close</button><h2>Kitchen Safety on your tablet</h2><p>On iPad: open this portal in Safari, tap Share, then Add to Home Screen and Open as Web App.</p><p>On Android: use your browser’s Install app or Add to Home screen option.</p><p class="help">HTTPS is required. Keep the tablet online to view current records and submit readings. Drafts on this device are not saved records.</p></dialog></body></html>';
}
function frontend_home():void{
 $s=site();$date=local_time(now(),'Y-m-d');$summary=day_summary($s,$date);$cooling=rows("SELECT r.* FROM ks_records r WHERE site_id=? AND status='pending' AND NOT EXISTS(SELECT 1 FROM ks_events e WHERE e.record_id=r.id AND e.type IN ('cooling_complete','resolve')) ORDER BY observed_at",[$s['id']]);
 echo '<section class="k-start"><div class="k-start-heading"><img src="'.e(base_url('assets/brand/kitchen-safety.svg')).'" alt="Kitchen Safety" width="68" height="68"><div><p class="eyebrow">KITCHEN SAFETY</p><h1>'.e($s['name']).'</h1><p class="muted">'.e(local_time(now(),'l j F · H:i')).'</p></div><form method="post" class="k-site-picker">'.csrf().'<input type="hidden" name="action" value="switch_site"><label class="sr-only" for="kitchen-switch">Kitchen</label><select name="site_id" id="kitchen-switch">';foreach(sites() as $x)echo '<option value="'.(int)$x['id'].'" '.($x['id']===$s['id']?'selected':'').'>'.e($x['name']).'</option>';echo '</select><button class="btn small">Switch kitchen</button></form></div><section class="k-install-card" data-install-card><span>'.icon('box').'</span><div><strong>Keep this on the kitchen tablet</strong><p>Open it like an app. Record temperatures without a staff login.</p></div><button class="btn primary" type="button" data-install>Install app</button></section><h2 class="k-question">What do you need?</h2><div class="k-choices">';
 $choices=[['new','thermo','Record temperatures','Fridges, freezers and every food batch.','No staff login needed','cold'],['history','history','Date records','Find readings, notes and follow-up actions.',$summary['records'].' readings today','history'],['cooling','thermo','Cooling records','Start a cooling check and record the finish.',count($cooling).' cooling in progress','warm'],['new&kind=task','check','Daily checks','Opening, closing and kitchen routines.',$summary['recorded_slots'].' / '.$summary['scheduled'].' scheduled checks recorded','routine']];
 foreach($choices as [$link,$ic,$title,$desc,$meta,$theme])echo '<a class="k-choice '.$theme.'" href="'.e(url('p='.$link)).'"><div class="k-choice-art">'.icon($ic).'</div><div class="k-choice-body"><h3>'.e($title).'</h3><p>'.e($desc).'</p><small>'.e($meta).'</small></div><span class="k-choice-go">'.icon('arrow').'</span></a>';echo '</div></section>';
 if($cooling){echo '<section class="card"><div class="card-head"><h2>Cooling in progress</h2><span class="count">'.count($cooling).'</span></div>';records_table($cooling);echo '</section>';}
 $items=scheduled_items($s,$date);echo '<section class="card"><div class="card-head"><h2>Today’s checks</h2><span class="help">'.e(local_time(now(),'D j M')).'</span></div>';
 if(!$items)empty_state('No scheduled checks yet','A manager can add fridges, freezers, holding units and daily check times in the admin panel.');
 foreach($items as $x){$link=$x['record']?'p=record&id='.$x['record']['id']:'p=new&kind='.$x['kind'].'&asset='.$x['id'].'&slot='.$x['slot'];echo '<div class="schedule-row"><time>'.e($x['slot']).'</time><div class="grow"><strong>'.e($x['name']).'</strong><small>'.e(KINDS[$x['kind']]??'Routine check').'</small></div>'.badge($x['state']).'<a class="btn small" href="'.e(url($link)).'">'.($x['record']?'View record':'Record').'</a></div>';}
 echo '</section><p class="k-floor-note">Record the actual measured temperature. If a check was missed, tell a manager rather than inventing a reading.</p>';
}
